<?php require 'config/db.php';require 'includes/functions.php';require_role('donor');$uid=user()['id'];$p=$conn->query("SELECT * FROM donor_profiles WHERE user_id=$uid")->fetch_assoc();$matches=$conn->query("SELECT rm.*,br.patient_name,br.blood_group need_group,br.priority,br.needed_by,h.name hospital_name FROM request_matches rm JOIN blood_requests br ON br.id=rm.request_id LEFT JOIN hospitals h ON h.id=br.hospital_id WHERE rm.donor_id=$uid ORDER BY rm.created_at DESC");$notes=$conn->query("SELECT * FROM notifications WHERE user_id=$uid ORDER BY created_at DESC LIMIT 6");$pageTitle='Donor Dashboard';include 'includes/header.php';?>
<section class="dashboard"><div class="container"><div class="dashboard-head"><div><span class="kicker">Donor readiness</span><h1>Welcome, <?=e(explode(' ',user()['name'])[0])?></h1><p>Your blood group, availability and compatible emergency alerts.</p></div><a class="btn btn-primary" href="requests.php">View active requests</a></div><div class="metric-grid"><div class="metric"><div class="icon"><i class="fa-solid fa-droplet"></i></div><strong><?=e($p['blood_group'])?></strong><span>Blood group</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-heart"></i></div><strong><?=$p['total_donations']?></strong><span>Donations</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-signal"></i></div><strong><?=$p['response_rate']?>%</strong><span>Response rate</span></div><div class="metric"><div class="icon"><i class="fa-solid fa-circle"></i></div><strong><?=e(ucwords(str_replace('_',' ',$p['availability'])))?></strong><span>Availability</span></div></div><div class="dash-grid"><div class="panel"><h3>Your emergency matches</h3><div class="table-wrap"><table class="table"><tr><th>Patient</th><th>Need</th><th>Distance</th><th>Score</th><th>Status</th><th></th></tr><?php while($m=$matches->fetch_assoc()):?><tr><td><?=e($m['patient_name'])?><br><small><?=e($m['hospital_name'])?></small></td><td><b><?=e($m['need_group'])?></b></td><td><?=$m['distance_km']?> km</td><td><?=$m['readiness_score']?>%</td><td><?=e($m['match_status'])?></td><td><a class="btn btn-sm btn-ghost" href="request-view.php?id=<?=$m['request_id']?>">Open</a></td></tr><?php endwhile;?></table></div></div><div class="panel"><h3>Notifications</h3><?php while($n=$notes->fetch_assoc()):?><a class="notification" href="<?=e($n['link']?:'#')?>"><div class="n-icon"><i class="fa-solid fa-bell"></i></div><div><b><?=e($n['title'])?></b><span><?=e($n['message'])?></span></div></a><?php endwhile;?></div></div></div></section><?php include 'includes/footer.php';?>
